<?php require_once dirname(__DIR__).'/includes/functions.php'; if(is_admin())redirect('/admin/index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$stmt=db()->prepare("SELECT * FROM users WHERE email=? AND status='active' LIMIT 1");$stmt->execute([strtolower(trim($_POST['email']))]);$u=$stmt->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$u['id'];$_SESSION['admin_name']=$u['name'];$_SESSION['admin_role']=$u['role'];redirect('/admin/index.php');}$error='Invalid email or password.';}?><!doctype html><html><head><meta charset="utf-8"><title>CMS Login</title><link rel="stylesheet" href="<?=BASE_URL?>/public/assets/style.css"></head><body class="section alt"><div class="container content"><div class="card card-body"><h1>CMS Sign in</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password" required><button class="btn">Sign in</button></form></div></div></body></html>

